.project-action.focus-ring {
  --trm-focus-ring-width: 4px;
  --trm-focus-ring-color: #075985;
  --trm-focus-ring-offset: 3px;
  outline-offset: var(--trm-focus-ring-offset);
}

@use 'tremplin/scss/root' with (
  $root-tokens: (
    '--trm-focus-ring-width': 4px,
    '--trm-focus-ring-offset': 3px
  )
);
@use 'tremplin/scss';

@use 'tremplin/scss/mixins/focus-ring' as focus;
.project-action:focus-visible {
  @include focus.focus-ring(true, #075985);
}

.project-lift.hover-lift {
  --trm-hover-lift-transition-duration: 120ms;
  --trm-hover-lift-transition-timing: ease-out;
  --trm-hover-lift-transform: translateY(-.5rem);
  --trm-hover-lift-box-shadow: 0 .25rem .75rem rgb(20 24 38 / .16);
}

@use 'tremplin/scss/helpers/hover-lift' with (
  $hover-lift-tokens: (
    '--trm-hover-lift-transform': translateY(-.5rem),
    '--trm-hover-lift-transition-duration': .12s
  )
);
@use 'tremplin/scss';

@media (prefers-reduced-motion: reduce) {
  .hover-lift { --trm-hover-lift-transform: none; }
}

.project-icon-link.icon-link {
  --trm-icon-link-gap: .5rem;
  --trm-icon-link-icon-size: 1.1em;
  --trm-icon-link-icon-transition: transform 120ms ease;
  --trm-icon-link-transform: translate3d(-.15em, 0, 0);
}

@use 'tremplin/scss/helpers/icon-link' with (
  $icon-link-tokens: (
    '--trm-icon-link-gap': .5rem,
    '--trm-icon-link-icon-size': 1.1em
  )
);
@use 'tremplin/scss';

@use 'tremplin/scss/config' with (
  $breakpoints: (base: 0, compact: 30rem, wide: 60rem)
);
@use 'tremplin/scss/helpers/position';

.project-stack {
  --trm-stack-flex: 0 0 auto;
  --trm-stack-align-self: center;
}

@use 'tremplin/scss/layout/breakpoints' as bp;
.project-frame { @include bp.set-container(inline-size, project-frame); }
.project-items { display: flex; flex-direction: column; }
@include bp.container-breakpoint-up(sm, project-frame) {
  .project-items { flex-direction: row; }
}

@use 'tremplin/scss/helpers/stretched-link' with (
  $stretched-link-pseudo-element: before,
  $stretched-link-tokens: ('--trm-stretched-link-z-index': 2)
);
@use 'tremplin/scss';

@use 'tremplin/scss/mixins/text-truncate' as text;
.project-label {
  max-inline-size: 16rem;
  @include text.text-truncate();
}

.project-rule.vr {
  --trm-vr-border-width: 2px;
  --trm-border-color: var(--trm-fg-body);
  min-height: 2rem;
}

@use 'tremplin/scss/mixins/visually-hidden' as hidden;
.project-sr-text { @include hidden.visually-hidden(); }
.project-skip-link { @include hidden.visually-hidden-focusable(); }

